// Verify that the __attribute__((aie_propagate_restrict)) spelling emits the
// "aie-propagate-restrict" string function attribute, and that functions
// without it do not carry the attribute.

// RUN: %clang --target=aie2 -O2 -S -emit-llvm %s -o - | FileCheck %s --check-prefixes=CHECK,AIE2
// RUN: %clang --target=aie2p -O2 -S -emit-llvm %s -o - | FileCheck %s --check-prefixes=CHECK,AIE2P
// RUN: %clang --target=aie2ps -O2 -S -emit-llvm %s -o - | FileCheck %s --check-prefixes=CHECK,AIE2PS

// CHECK: Function Attrs: mustprogress nofree norecurse nosync nounwind willreturn memory(argmem: readwrite)
// CHECK-LABEL: define dso_local void @with_attribute(
// CHECK-SAME: ptr writeonly captures(none) initializes((0, 4)) [[A:%.*]], ptr readonly captures(none) [[B:%.*]]) local_unnamed_addr #[[ATTR0:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[TMP0:%.*]] = load i32, ptr [[B]], align 4, !tbaa [[TBAA2:![0-9]+]]
// CHECK-NEXT:    store i32 [[TMP0]], ptr [[A]], align 4, !tbaa [[TBAA2]]
// CHECK-NEXT:    ret void
//
__attribute__((aie_propagate_restrict)) void with_attribute(int *a, int *b) { *a = *b; }

// CHECK: Function Attrs: mustprogress nofree norecurse nosync nounwind willreturn memory(argmem: readwrite)
// CHECK-LABEL: define dso_local void @without(
// CHECK-SAME: ptr writeonly captures(none) initializes((0, 4)) [[A:%.*]], ptr readonly captures(none) [[B:%.*]]) local_unnamed_addr #[[ATTR1:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[TMP0:%.*]] = load i32, ptr [[B]], align 4, !tbaa [[TBAA2]]
// CHECK-NEXT:    store i32 [[TMP0]], ptr [[A]], align 4, !tbaa [[TBAA2]]
// CHECK-NEXT:    ret void
//
void without(int *a, int *b) { *a = *b; }
